import os, sys
from collections import defaultdict as dd, deque as dq, Counter as dc

def getInt():
	return int(input())

def getStrs():
	return input().split()

def getInts():
	return list(map(int, input().split()))

def getStr():
	return input()

def listStr():
	return list(input())

def getMat(n):
	return [getInts() for _ in range(n)]

def getBin():
	return list(map(int, list(input())))

def isInt(s):
	return '0' <= s[0] <= '9'

def ceil_(a, b):
	return a // b + (a % b > 0)
MOD = 10 ** 9 + 7

def solve():
	(N, M, L) = getInts()
	counts = [0] * N
	G = [[[] for _ in range(26)] for _ in range(N)]
	S = listStr()
	vertex = listStr()
	U = [u - 1 for u in getInts()]
	V = [v - 1 for v in getInts()]
	orda = ord('a')
	extras_ = [dd(int)] * 26
	for i in range(M):
		(u, v) = (U[i], V[i])
		G[u][ord(vertex[v]) - orda].append(v)
		G[v][ord(vertex[u]) - orda].append(u)
		if vertex[u] == vertex[v]:
			extras_[ord(vertex[u]) - orda][min(u, v), max(u, v)] += 1
	for (i, v) in enumerate(vertex):
		if v == S[0]:
			counts[i] += 1
	for i in range(1, L):
		targ = ord(S[i]) - orda
		new_counts = [0] * N
		for j in range(N):
			for x in G[j][targ]:
				new_counts[x] += counts[j]
				new_counts[x] %= MOD
		counts = list(new_counts)
	ans = sum(counts)
	if len(set(S)) == 1:
		for (key, val) in extras_[ord(S[0]) - orda].items():
			ans -= pow(val, L - 1, MOD)
	return ans % MOD
for _ in range(getInt()):
	print(solve())
